import torch
from flask import Flask, request, jsonify
from transformers import AutoTokenizer, AutoModelForSequenceClassification

app = Flask(__name__)

MODEL_DIR = "/app/model_cache/sentiment_model"

tokenizer = AutoTokenizer.from_pretrained(MODEL_DIR)
model = AutoModelForSequenceClassification.from_pretrained(MODEL_DIR)
model.eval()

# Build label -> name mapping (e.g. {'0': 'NEGATIVE', '1': 'POSITIVE'})
label_map = {i: name for i, name in enumerate(model.config.id2label.values())}
# Normalize to lowercase for matching
label_map = {k: v.lower() for k, v in label_map.items()}


def analyze(text):
    inputs = tokenizer(text, return_tensors="pt", truncation=True, padding=True, max_length=512)
    with torch.no_grad():
        outputs = model(**inputs)
    probs = torch.softmax(outputs.logits, dim=-1)[0]
    scores = {label: probs[i].item() for i, label in label_map.items()}
    return scores


@app.route("/sentiment", methods=["POST"])
def sentiment():
    data = request.get_json(silent=True)
    if not isinstance(data, dict) or "text" not in data:
        return jsonify({"error": "Request body must be JSON with a 'text' field."}), 400

    text = data["text"]
    if not isinstance(text, str):
        return jsonify({"error": "The 'text' field must be a string."}), 400

    try:
        scores = analyze(text)
    except Exception as e:
        return jsonify({"error": f"Failed to analyze sentiment: {e}"}), 400

    pos = scores.get("positive", 0.0)
    neg = scores.get("negative", 0.0)
    sentiment_label = "positive" if pos >= neg else "negative"

    return jsonify({
        "sentiment": sentiment_label,
        "confidence": {
            "positive": pos,
            "negative": neg,
        },
    })


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
EOF

