import json, urllib.request, urllib.error

def post(payload):
    req = urllib.request.Request(
        "http://localhost:5000/sentiment",
        data=json.dumps(payload).encode(),
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req) as r:
            return r.status, r.read().decode()
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode()

print("POSITIVE:", post({"text": "This movie was absolutely wonderful and fantastic!"}))
print("NEGATIVE:", post({"text": "This is terrible, I hated every minute of it."}))
print("ERROR (missing text):", post({}))
